style.css:
@-moz-document domain("roblox.com") {
:root {
  --my-pink: #f3dce4;
  --my-blush: #faedf1;
  --my-cream: #fffaf7;
  --my-rose: #d5a3b2;
  --my-text: #806b70;
}

/* main background */
body {
  background: var(--my-blush) !important;
  color: var(--my-text) !important;
}

/* top navigation */
.rbx-navbar-header,
.navbar-header,
#right-navigation-header,
.rbx-navbar {
  background: #e9c5d1 !important;
}

/* navigation text */
.rbx-navbar a,
.navbar-header a,
#right-navigation-header button {
  color: #805d6b !important;
}

/* search bar */
#navbar-search-input,
.navbar-search .input-group,
.navbar-search .form-control {
  background: var(--my-cream) !important;
  color: var(--my-text) !important;
  border: 1px solid #e4bdca !important;
  border-radius: 20px !important;
}

/* buttons */
button {
  border-radius: 12px !important;
}

/* links */
a {
  color: #bd879b !important;
}

/* images */
img {
  border-radius: 10px !important;
}

/* bunny decoration */
body::before {
  content: "୨୧ ᕱ⑅ᕱ ୨୧";
  position: fixed;
  top: 80px;
  right: 20px;
  color: #c58fa1;
  font-size: 23px;
  pointer-events: none;
  z-index: 9999;
}
}
